import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"Table Extensions in AL","description":"","frontmatter":{},"headers":[],"relativePath":"tables-fields-and-business-data/table-extensions.md","filePath":"tables-fields-and-business-data/table-extensions.md"}`),a={name:`tables-fields-and-business-data/table-extensions.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="table-extensions-in-al" tabindex="-1">Table Extensions in AL <a class="header-anchor" href="#table-extensions-in-al" aria-label="Permalink to “Table Extensions in AL”">​</a></h1><p>So far, we&#39;ve been creating our own tables, such as <code>Course</code>. But what happens when you need to add information to a table that already exists in Business Central?</p><p>For example, suppose Business Central already has a <strong>Customer</strong> table, and your company wants to store each customer&#39;s website URL. You want to add that information without modifying Microsoft&#39;s original table.</p><p>That&#39;s where <strong>table extensions</strong> come in.</p><h2 id="what-is-a-table-extension" tabindex="-1">What is a table extension? <a class="header-anchor" href="#what-is-a-table-extension" aria-label="Permalink to “What is a table extension?”">​</a></h2><p>A table extension lets you extend an existing table by adding things such as:</p><ul><li>New fields.</li><li>Additional field groups.</li><li>Certain triggers and validation logic.</li></ul><p>You don&#39;t replace the original table, and you don&#39;t directly modify Microsoft&#39;s base application. Instead, your extension adds functionality to it.</p><p><strong>Think of it this way:</strong></p><ul><li><code>table</code> creates a new table.</li><li><code>tableextension</code> adds to an existing table.</li></ul><p>This is an important part of Business Central&#39;s extensibility model: you can customize the application while keeping your changes separate from the base application.</p><h2 id="create-our-first-table-extension" tabindex="-1">Create our first table extension <a class="header-anchor" href="#create-our-first-table-extension" aria-label="Permalink to “Create our first table extension”">​</a></h2><p>Let&#39;s make this practical.</p><p>We&#39;ll extend Business Central&#39;s built-in <strong>Customer</strong> table by adding a field called <code>Training Level</code>.</p><p>Imagine we&#39;re customizing Business Central for a training company and want to classify customers according to their training level.</p><h3 id="step-1-create-the-al-file" tabindex="-1">Step 1: Create the AL file <a class="header-anchor" href="#step-1-create-the-al-file" aria-label="Permalink to “Step 1: Create the AL file”">​</a></h3><p>In VS Code, create a new file called <code>CustomerExt.TableExt.al</code>.</p><h3 id="step-2-add-the-following-code" tabindex="-1">Step 2: Add the following code <a class="header-anchor" href="#step-2-add-the-following-code" aria-label="Permalink to “Step 2: Add the following code”">​</a></h3><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>namespace LearningAl;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>tableextension 50104 CustomerExt extends Customer</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    fields</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        field(50104; &quot;Training Level&quot;; Text[30])</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            Caption = &#39;Training Level&#39;;</span></span>
<span class="line"><span>            DataClassification = CustomerContent;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Let&#39;s break down the new syntax.</p><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>tableextension</code></td><td>Declares a table extension object.</td></tr><tr><td><code>50104</code></td><td>The object ID of our extension.</td></tr><tr><td><code>CustomerExt</code></td><td>The name of our extension object.</td></tr><tr><td><code>extends Customer</code></td><td>Specifies the existing table we want to extend.</td></tr><tr><td><code>fields</code></td><td>Contains the additional fields we&#39;re introducing.</td></tr><tr><td><code>field(50104; &quot;Training Level&quot;; Text[30])</code></td><td>Declares our new field, using field ID <code>50104</code>.</td></tr></tbody></table><p><strong>Notice something important:</strong> We use <code>50104</code> for both the extension object ID and the new field ID. That&#39;s allowed because object IDs and field IDs belong to different numbering scopes. However, each ID must be unique within its own relevant scope.</p><p>Also, <code>Customer</code> is an existing Business Central table. We&#39;re not creating another Customer table or copying customer records into a new table. <a href="https://learn.microsoft.com/uk-ua/dynamics365/business-central/dev-itpro/developer/devenv-table-ext-object" target="_blank" rel="noreferrer">Microsoft Learn</a></p><h3 id="step-3-publish-the-extension" tabindex="-1">Step 3: Publish the extension <a class="header-anchor" href="#step-3-publish-the-extension" aria-label="Permalink to “Step 3: Publish the extension”">​</a></h3><ol><li>Save the file.</li><li>Press <strong>F5</strong> to publish.</li><li>Wait for publishing to complete successfully.</li></ol><p>At this point, you&#39;ve defined the new field, but you haven&#39;t necessarily made it visible on any page.</p><p>That&#39;s an important distinction: <strong>tables store data; pages provide the user interface for viewing and editing it.</strong></p><h2 id="how-do-we-see-our-new-field" tabindex="-1">How do we see our new field? <a class="header-anchor" href="#how-do-we-see-our-new-field" aria-label="Permalink to “How do we see our new field?”">​</a></h2><p>Our next task is to expose <code>Training Level</code> on the Customer Card page.</p><p>For now, here&#39;s the concept without going deep into page extensions:</p><ul><li><strong>Table extension:</strong> Adds the <code>Training Level</code> field to the Customer table.</li><li><strong>Page extension:</strong> Adds that field to an existing Customer Card page so users can see and edit it.</li></ul><p>We&#39;ll cover page extensions properly when we revisit pages in the next chapter.</p><p>You can read Microsoft&#39;s documentation on the <a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-table-ext-object" target="_blank" rel="noreferrer">Table extension object</a> for more details. <a href="https://learn.microsoft.com/uk-ua/dynamics365/business-central/dev-itpro/developer/devenv-table-ext-object" target="_blank" rel="noreferrer">Microsoft Learn</a></p><hr><h2 id="rules-to-remember" tabindex="-1">Rules to remember <a class="header-anchor" href="#rules-to-remember" aria-label="Permalink to “Rules to remember”">​</a></h2><ol><li><strong>You cannot extend every table.</strong> The target table must support extensibility.</li><li><strong>Don&#39;t modify Microsoft&#39;s original table directly.</strong> Use an extension to add your custom fields.</li><li><strong>Use appropriate field IDs.</strong> Your custom IDs must not conflict with IDs already used in the target table or by other extensions.</li><li><strong>Existing data remains part of the same table.</strong> A table extension adds fields to the existing table rather than creating a separate table.</li><li><strong>Adding a field doesn&#39;t automatically display it on a page.</strong> You may need a page extension.</li></ol>`,36)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};